数据基本数据类型先声明再使用声明数据实际上有两个作用

需占内存的大小, 能表示的数据范围
允许的操作种类

整数 int修饰词
short (int) %hd
long (int) %ld %lo %lx 要把一个较小的数看做 long，在数后面加 l 或 L（建议使用 L）
long long (int) %lld
unsigned (int) %u

可移植类型
&lt;stdint.h&gt;
&lt;inttypes.h&gt;

浮点数 float存储中的表示首位作为符号位，一部分作为值（尾数）部分，另一部分作为指数部分，根据指数部分的大小使小数点移动，因此称为“浮点数”
声明形式
1.14
5.e-2
.45E-6
作为一个整体，不要在其中加入空格



注：NaN 为浮点数
修饰词
float %f ​ 后面 8 位：127+C 最后 23 位：M-1, 丢弃小数点
double %lf ​ %le ​ %la ​ a 表示十六进制的浮点数后面 11 位：1023+C 最后 52 位：M-1,丢弃小数点
long double %Lf （注意是大写的 L，且只有一个）

浮点数的上溢和下溢精度不足导致的数据丢失
字符型 char实际上的字符是以数值形式存储的，由于输出时上下文的区别会输出字符或数值
其他布尔值 Bool值为 true 或 false
一般表达式的真值为 int ​ 类型或 &lt;stdbool.h&gt; 使用 bool，值为 true 和 false
复数 Complex虚数 Imaginary派生数据类型指针 *声明&#x2F;初始化int *num; //一个指向整型的指针
float *ft[10]; //一个含有10个指针的数组，每个指针指向一个float
int board[8][9];//一个二维数组
int **ptr;//一个指向指针的指针，该指针指向一个整数
int (* rusks)[10];//一个指针，指向一个有10个元素的数组
int * oof[3][4];//一个数组，每个元素都是一个指向整数的指针
int (* uuf)[3][4];//一个指向二维数组的指针
int (* uof[3])[4];//声明一个含有三个指针的数组，每个指针指向一个含有4个整数的数组

不要把一个整数(例外:0)赋值给一个指针变量0&#x2F;NULL 常用于表示一个指针变量暂未指向一个变量指针必须指向同类型元素，但可以这样：
int a = 5;
void * p = &amp;a;

优先级：[]​&#x3D;()​&gt;*​
操作++&#x2F;–&#x2F;自身递增&#x2F;递减，移向下一个元素（如果是数组），因此指针的类型和数组才需要对应，因为要移动对应的字节数
+n&#x2F;-n向后 n 个&#x2F;前 n 个元素移动
指针相减得到两个指针相距的元素个数
*解引用，得到指针所指地址的内容，注意不要解引用没有初始化的指针！
&amp;取地址，得到存放指针的地址，即指向指针的指针
指向多维数组的指针int (*pz)[2]; //pz指向一个含2个int的数组
int *px[2]; //px是一个含有两个指针的数组，指针指向int
int pc[2][3]; //pc是一个含有两个指针的数组，每个指针指向一个含有3个int的数组

数组定义由数据类型相同的一系列元素组成
声明&#x2F;初始化int num[42] = {[1] = 6}; //指定位置初始化，若有特定位置被初始化则其他未操作位置都会为0
char st[114] = {&#39;s&#39;,&#39;k&#39;,&#39;a&#39;,&#39;d&#39;,&#39;i&#39;,&#39;\0&#39;}; //若如st已创建内容，则可省略`[]`中的数值，会为数组自动分配相应的大小
char *s[10]; //一个指向数组的指针，该数组含10个元素

数组的下标从 0 开始，到 SIZE-1数组的名称即为一个指向数组首元素的指针可以用负数表示下标，即往回走
变长数组（VLA）可以先获取 n（如输入），再创建数组因为数组需要划分一个连续的空间，所以原本会在程序运行前为数组分配空间防止它扰乱进程，新版的 C 可以在运行过程中创建数组但还是推荐使用 malloc()
int example(int n , int m , int st[n][m]); //传参数时要把n,m放前面，或者略去所有形参，用*代替[]中的参数

多维数组传给函数时需要以 ar[][n][m] 的格式
int num[4][2]; //num是一个拥有4个元素的数组，每一个元素都是一个含有2个int的数组，即num存着4个地址

遍历数组int main(void)
{
	int i,n=10;
	int num[10];
	for (i = 0 ; i &lt; n ; i++)
			printf(&quot;%d &quot;,num[i]); //使用[]来获取数组内的值（指针表示法）
	for (i = 0 ; i &lt; n ; i++)
			printf(&quot;%d &quot;,*(num+i)); //使用*来获取数组内的值（数组表示法）
	return 0;
}

传参时，可以传数组，也可以传入数组的首元素的指针和末元素的指针
复合字面量相当于创建一个没有名称的数据（匿名数据），可以在给函数传数据的时候用，就可以不用再声明一个数据了
(int [2]){10,20}
int *pt1;
pt1 = (int[2]){10,20};

字符串本质是一个 char 类型的数组，且以 &#39;\0&#39; 结尾，因此必须为数组多留一位来存放 &#39;\0&#39;
定义字符串常量(string constant)
双引号 &quot;&quot; 括起来的内容，也叫字符串字面量(string literal)
编译器会自动加入 \0 在末尾
如果字符串字面量之间没有间隔或用空白字符分割，会视为一个

char a[50] = &quot;hello &quot; &quot;world&quot;;
//等价于
char b[50] = &quot;hello world&quot;;

char 类型数组其他未初始化的位置默认为 \0
const char m1[40] = {&#39;h&#39;,&#39;e&#39;,&#39;l&#39;,&#39;l&#39;,&#39;o&#39;};  //不是一个字符串，只是一个char数组
const char m2[40] = {&#39;h&#39;,&#39;e&#39;,&#39;l&#39;,&#39;l&#39;,&#39;o&#39;,&#39;\0&#39;}; //结尾必须有&#39;\0&#39;才是字符串
const char m3[40] = &quot;hello&quot;;  //更加简便，会自动添加&#39;\0&#39;

指向 char 的指针const char * pt = &quot;hello&quot;;
//基本等价于
const char ar[] = &quot;hello&quot;;

数组和指针的区别
pt 的值可以改变（指针前后移动或指向另一个字符串），但 ar 的值不可改变（不能进行自增自减，数组名不是变量，但可以进行指针加法操作）
编译器使用内存中的一个副本来表示所有完全相同的字符串字面量

char * p1 = &quot;hello&quot;;
p1[0] = &quot;c&quot;;
printf(&quot;hello&quot;);
printf(&quot;\n %s&quot;,&quot;hello&quot;);
//理论上会输出：
//cello
//cello
//但实际上没有输出，可能是编译器区别，所以如果打算修改字符串，就不要用指针指向字符串字面量

I&#x2F;Ofgets()gets_s与 fgets 基本相同，但是只能从 stdin 中读取，所以只需两个参数，且会舍弃换行符gets_s(words,STLEN)
s_getschar *s_gets(char st[],int n) //读取一行字符串
{
	char *ret_val,*find;
	ret_val = fgets(st,n,stdin);
	if (ret_val)
	{
		find = strchr(st,&#39;\n&#39;);
		if (find)
			*find = &#39;\0&#39;;
		else
			while (getchar() != &#39;\n&#39;)
				continue;
	}
	return ret_val;
}

scanf()puts()fputs()printf()字符串函数strlen()size_t strlen(const char *_Str)
获取字符串长度，不包括 \0
strcat() &#x2F; strncat()
char *strcat(char *__restrict__ _Dest, const char *__restrict__ _Source)
char *strncat(char *__restrict__ _Dest, const char *__restrict__ _Source, size_t _Count)

将 Source 拼接到 Dest 上，会将 Dest 末尾的 \0 删去，Count 指定 Source 的长度返回 Dest
strcmp() &#x2F; strncmp
int strcmp(const char *_Str1, const char *_Str2)
int strncmp(const char *_Str1, const char *_Str2, size_t _MaxCount)

比较字符串在机器排序中的先后（如 AASCII 码），相等返回 0；不相等的情况下，视为 Str1-Str2，会得到正值或负值
MaxCount 表示最多会比较到的长度
strcpy &#x2F; strncpy()
char *strcpy(char *__restrict__ _Dest, const char *__restrict__ _Source)
char *strncpy(char *__restrict__ _Dest, const char *__restrict__ _Source, size_t _Count)

将 Source 的内容拷贝到 Dest 中，要注意不要溢出，返回 Dest
Count 指定 Source 拷贝的长度
sprintf()int sprintf(char *__restrict__ _Dest, const char *__restrict__ _Format, ...)
将多个元素合成一个字符串，Dest 为目标字符串，打印结果会进入 Dest 中而不是屏幕上
strchr() &#x2F; strrchr()
char *strchr(const char *_Str, int _Val)
返回字符串中首次(包含’\0）出现 Val 的地址，不存在则返回 NULL


char *strrchr(const char *_Str, int _Ch)
返回字符串中最后一次（包含’\0’）出现 Ch 的地址，不存在则返回 NULL



strpbrk()char *strpbrk(const char *_Str, const char *_Control)
如果 Str 中包含 Control 中的任意字符，则函数返回指向 Str 首元素的指针；不包含则返回 NULL
strstr()char *strstr(const char *_Str, const char *_SubStr)
返回 Str 中 SubStr 出现的首位置，未出现则返回 NULL​
字符串与数值转换atoi()atof()atol()字符串转为 int&#x2F;double&#x2F;long
如果字符串是以数字开头的字母数字混合字符串，则会取开头的数字直到字母
strtol()strtoul()strtod()字符串转为 long&#x2F;unsigned long&#x2F;double
可以识别和报告字符串中而的首字符是否是数字
结构创建struct book  //struct为关键字，book为标记
{
	char title[MAX];
	char author[MAX];
	float value;
};  //不要忘了分号

struct book library;  //声明一个book类型变量，变量名为library
struct book *pt;  //声明一个指向book的指针

//如果这个结构只需用到一次，可以：
struct  //无需结构标记
{
	char title[MAX];
	char author[MAX];
	float value;
} library;

//初始化
struct book library = {
	&quot;Golden Age&quot;,
	&quot;Ji Ci&quot;,
	11.45
}; //可以不用换行，仅仅是为了增加可读性

//指定初始化
struct book library = {
	.value = 11.45;  //也可以单独为其中一个成员赋值，而其他成员保持空的状态
	.title = &quot;Golden Age&quot;,
	.author = &quot;Ji Ci&quot;
};  //若多次对同一个成员进行赋值，最后一次会成为最终的结果

struct book library[10] = {
	[2]={
        .foclen = 500,
        .fstop = 2,
        .brand = &quot;Remarkata&quot;
    }
};//为一个结构数组中的其中一个元素初始化，其他初始化为0，字符串为空

访问成员结构成员运算符：.，相当于下标的作用​library.title
结构数组
struct book library[NUM] ​ 生成一个 book 类型变量的数组
library[count].title ​ 类似格式进行访问

嵌套结构struct city
{
	int population;
	struct book library;
};

//访问
struct city ShangHai;
printf(&quot;%s&quot;,ShangHai.library.title);

指向结构的指针struct book * pt;
pt = &amp;library;  //注意，与数组不同，结构名不代表其地址
printf(&quot;%f&quot;,pt -&gt; value);  //指针使用-&gt;来访问成员
printf(&quot;%s&quot;,(*pt).title);  //先将pt解引用得到library，再使用结构的访问成员的方式来访问，注意()是必须的，&quot;.&quot;的优先级高于&quot;*&quot;

向函数传递结构的信息传递结构本身void show(const struct book);
……
show(libaray);  //注意结构名本身不代表结构的地址
……
void show(const struct book library)
{
	printf(&quot;%s is written by %s and values %f&quot;, library.title , library.author , library.value);
}
//使用传递结构本身可能会导致程序运行速度变慢
//而且当需要改变结构所含的值时，函数需要返回结构

传递结构指针void show(const struct book * pt);  //pt可省略
……
show(&amp;libaray);  //注意结构名本身不代表结构的地址
……
void show(const struct book * pt)
{
	printf(&quot;%s is written by %s and values %f&quot;, pt-&gt;title , pt-&gt;author , pt-&gt;value);
}

传递结构成员单独的将结构的成员的值提取出来向结构传递
赋值
如果两个结构类型相同，则可以直接进行赋值（不是只给地址）
也可以在进行初始化的时候直接赋其另一个相同类型的值

在结构内使用指针//需要使用malloc()为指针分配空间，不能让指针空指
struct namect
{
	char * fname;
	char * lname;
};
……
struct namect * YY;
YY -&gt; fname = (char *)malloc(strlen(temp)+1);  //sizeof(char)(=1)可以省去
strcpy(YY -&gt; fname , temp);  //malloc()处理字符串常规操作
……
free(YY -&gt; fname);

结构的复合字面量reader = (struct book) {&quot;Arknight&quot;,&quot;Ocean Cat&quot;,&quot;10.10&quot;}

匿名结构struct person
{
	int id;
	struct {char first[20] ; char last[20]};
};
//访问
struct ZYY;
……
puts(ZYY.first);  //可以直接访问二级成员

伸缩型数组成员struct flex
{
	int count;
	double scores[];  //放在最后一个，作为伸缩型数组成员
}
struct flex * pt;
pt = malloc(sizeof(struct flex) + 5 * sizeof(double));
//在struct flex（不含scores）的基础上再有一个含5个元素的double数组

不应该声明 struct flex ​ 变量，而是应该声明对应的指针，再使用 malloc() ​ 为其创建空间使用含伸缩型数组的结构时：1）不能直接进行拷贝（直接拷贝会略去伸缩型数组而把其他的元素拷贝）,如果确实要拷贝使用 memcpy()​2）不要把结构直接传递给函数，应该传递指针3）不要使用带有伸缩型数组的结构作为数组，或者是其他结构的成员。
保存结构到文件中​fwrite(&amp;library , sizeof(struct book) , 1 , pbooks);​虽然使用起来比较方便，但是由于各个系统（甚至同一系统不同编译器）的二进制表示法不一定相同，所以可移植性很差
联合创建union hold
{
	int d;
	float f;
	double lf;
};
//联合的字节数会根据包含的最大的字节数确定
//把结构看作“和”，那就可以把联合看作“或”。联合在一个时间只能是它包含数据类型的其中一个，即只能存储一个值

使用union hold fit;
fit.d = 1;  //fit选择int类型
fit.f = 2.0; //fit选择float类型
fit.lf = 6.4; //fit选择double类型

//模拟实现一个选择
struct company……
struct person……
//比如一辆出租车，是属于个人还是公司，对于每个从属会有不同的属性，可以用union实现一个“选择”的功能
union owner
{
	struct company companyown;
	struct person personown;
};

匿名联合struct car_data
{
	……
	union
	{
		struct company companyown;
		struct person personown;
	};
};

枚举创建​enum spectrum{red , orange , yellow , green , blue , violet};​enum spectrum color;​相当于把这些符号常量作为标识符（但又不完全是）来使用，称为枚举符
enum 常量会给 enum 中的枚举符逐个赋值，默认从 0 开始递增，也可以赋值
enum spectrum {red , orange = 100 , yellow , green , blue = 1000 , violet};
//red == 0 , orange == 100 , yellow == 101 , green == 102 , blue == 1000 , violet == 1001

使用枚举类型的目的只是为了提高程序的可读性和可维护性，但枚举类型只能在内部使用，要用字符串进行比较来确定值
enum spectrum {red , orange = 100 , yellow , green , blue = 1000 , violet};
const char * colors [] = {&quot;red&quot;,&quot;orange&quot;……};
……
if (strcmp(choice,colors[color]) == 0)

