#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;
#define BUFSIZE 4096
void append(FILE *source , FILE *dest);
char * s_gets(char st[] , int n);
int main(int argc, char * argv[])
{
    FILE *fa , *fs;
    int files = 0;
    int count = 2;
    if (argc &gt; 2)
    {
        if ((fa = fopen(argv[1],&quot;a+&quot;)) == NULL)
        {
            fprintf(stderr,&quot;Can&#39;t open %s\n&quot;,argv[1]);
            exit(EXIT_FAILURE);
        }
        if ((setvbuf(fa,NULL,_IOFBF,BUFSIZE)) != 0)
        {
            fputs(&quot;Can&#39;t create output buffer\n&quot;,stderr);
            exit(EXIT_FAILURE);
        }
        while (argv[count])
        {
            if (strcmp(argv[1],argv[count]) == 0)
                fputs(&quot;Can&#39;t append file to itself\n&quot;,stderr);
            else if ((fs = fopen(argv[count],&quot;r&quot;)) == NULL)
                fprintf(stderr,&quot;Can&#39;t open %s\n&quot;,argv[count]);
            else
            {
                if (setvbuf(fs,NULL, _IOFBF , BUFSIZE) != 0)
                {
                    fputs(&quot;Can&#39;t create input buffer\n&quot;,stderr);
                    continue;
                }
                append(fs,fa);
                if (ferror(fs) != 0)
                    fprintf(stderr,&quot;Error in reading file &amp;s.\n&quot;,argv[count]);
                if (ferror(fa) != 0)
                    fprintf(stderr,&quot;Error in writing file %s.\n&quot;,argv[1]);
                fclose(fs);
                printf(&quot;File %s appended.\n&quot; , argv[count]);
                count++;
                files++;
                puts(&quot;Next file&quot;);
            }
        }
    }
    printf(&quot;Done appending. %d files appended.\n&quot;,argc-2);
    rewind(fa);
    printf(&quot;%s contents: \n&quot;,argv[1]);
    while ((ch = getc(fa)) != EOF)//output the source file
        putchar(ch);
    puts(&quot;Done displaying.&quot;);
    fclose(fa);
    return 0;
}
void append(FILE *source , FILE *dest)
{
    size_t bytes;
    static char temp[BUFSIZE];
    while ((bytes = fread(temp,sizeof(char),BUFSIZE,source)) &gt; 0)
        fwrite(temp,sizeof(char),bytes,dest);
}
char * s_gets(char st[] , int n)
{
    char * ret_val , *find;
    ret_val = fgets(st,n,stdin);
    if (ret_val)
    {
        find = strchr(st,&#39;\n&#39;);
        if (find)
            *find = &#39;\0&#39;;
        else
            while (getchar() != &#39;\n&#39;)
                continue;
    }
    return ret_val;
}

