double sum(int lim , ...)
{
    va_list ap;
    int i;
    double tot = 0;
    va_start(ap , lim);
    for (i = 0 ; i &lt; lim ; i++)
        tot += va_arg(ap,double);
    va_end(ap);
    return tot;
}

