          // 交换正负
          positive, negative = max(cur, cur*negative), min(cur, cur*positive)
       &#125; else &#123;
          // 不用交换，直接选取最优
          positive, negative = max(cur, cur*positive), min(cur, cur*negative)
       &#125;
