func getIntersectionNode(headA, headB *ListNode) *ListNode &#123;
    p1, p2 := headA, headB
    for p1 != p2 &#123;
        if p1 == nil &#123;
            p1 = headB
        &#125; else &#123;
            p1 = p1.Next
        &#125;
        if p2 == nil &#123;
            p2 = headA
        &#125; else &#123;
            p2 = p2.Next
        &#125;
    &#125;
    return p1
