T3. 回文链表
Given the head of a singly linked list, return true if it is a palindrome or false otherwise.


直接遍历链表，将元素提取到数组中再判断回文
快慢指针，慢指针遍历到中间结点，快指针遍历到末尾结点，反转一半链表，然后遍历两条链表判断是否相同 3. 从工程角度来说要恢复这个链表，但从做题角度直接返回结果就好

func isPalindrome(head *ListNode) bool &#123;
    slow, fast := head, head.Next
    // 快指针走到 nil 时停止: 奇数个节点
    // 快指针走到最后一个节点停止: 偶数个节点
    for fast != nil &amp;&amp; fast.Next != nil &#123;
        // 慢指针一次走一步
        slow = slow.Next
        // 快指针一次走两步
        fast = fast.Next.Next
    &#125;
    // 将链表以 slow 为分界线，将 slow 之后的进行反转
    l1 := head
    l2 := reverseList(slow.Next)
    // l2 长度小于等于 l1，但是最多只会少 1 个中间字符，不影响结果
    for l2 != nil &#123;
        if l1.Val != l2.Val &#123;
            return false
        &#125;
        l1 = l1.Next
        l2 = l2.Next
    &#125;
    return true
&#125;

// 反转链表
func reverseList(head *ListNode) *ListNode &#123;
    var prev *ListNode = nil
    cur := head
    for cur != nil &#123;
        next := cur.Next
        cur.Next = prev
        prev = cur
        cur = next
    &#125;
    // 如果 head == nil，返回的也是 nil
    return prev
&#125;

T10. 反转链表
