哈希表：想办法不重复遍历：遍历元素时，判断 num-1 是否存在，如果存在，则说明当前元素为“中间元素”，需要遍历的只有“开始元素”，即每一段连续序列的最小值。

func longestConsecutive(nums []int) int &#123;
    if len(nums) &lt;= 1 &#123;
       return len(nums)
    &#125;
    // set
    set := make(map[int]struct&#123;&#125;)
    for _, num := range nums &#123;
       set[num] = struct&#123;&#125;&#123;&#125;
    &#125;

    maxLen := 1
    for num, _ := range set &#123;
       // 如果num-1存在，说明不是起点，跳过
       if _, ok := set[num-1]; ok &#123;
          continue
       &#125;
       curNum, curLen := num+1, 1
       for _, ok := set[curNum]; ok; _, ok = set[curNum] &#123;
          curLen++
          curNum++
       &#125;
       maxLen = max(maxLen, curLen)

    &#125;
    return maxLen
&#125;

