    f := make([][]int, n)
    for i := range f &#123;
        f[i] = make([]int, m)
    &#125;
    ret := 0
    for i := 0; i &lt; n; i++ &#123;
        for j := 0; j &lt; m; j++ &#123;
            if matrix[i][j] == &#39;1&#39; &#123;
                if i == 0 || j == 0 &#123;
                    f[i][j] = 1
                &#125; else &#123;
                    f[i][j] = min(f[i-1][j], f[i][j-1], f[i-1][j-1]) + 1
                &#125;
                if f[i][j] &gt; ret &#123;
                    ret = f[i][j]
                &#125;
            &#125;
        &#125;
    &#125;
    return ret * ret
&#125;

