-1000 &lt;= target &lt;= 1000



回溯
动态规划

两个背包，一个背包 package_a 存放标记为正的元素，另一个背包 package_b 存放标记为负的元素。package_a - package_b = target。
设 nums 的元素和为sum, 可以列出方程：
$$\begin{align}\left{\begin{aligned}package_a - package_b &#x3D; target; \package_a + package_b &#x3D; sum;\end{aligned}\right.\end{align}$$
则  package_a = (sum + target) / 2。所以根据题意给的target和sum，可以求出package_a的值。
那这道题就可以转化为：给定一个大小为 package_a 的背包，有多少种组合方式能把背包装满？ 即 0-1 背包。
需要注意的是：sum + target 需要为非负偶数

非负：确保能凑出
偶数：确保划分时不会导致小数缺失

func findTargetSumWays(nums []int, target int) int &#123;
    var sum int = 0
    for _, num := range nums &#123;
       sum += num
    &#125;

    // 只有target + sum 为非负偶数时才有可能存在解
    n := sum + target
    if n &lt; 0 || n%2 == 1 &#123;
       return 0
    &#125;
    // package_a = (sum + target) / 2
    n /= 2
    f := make([]int, n+1)
    f[0] = 1
    for _, i := range nums &#123;
       for j := n; j &gt;= i; j-- &#123;
          f[j] += f[j-i]
       &#125;
    &#125;
    return f[n]
&#125;

