四、配置文件语法4.1 HCL (HashiCorp Configuration Language)Terraform 使用 HCL 语言编写配置文件。
基本语法# 单行注释

/*
多行注释
*/

# 1. 块 (Block)
resource &quot;aws_instance&quot; &quot;web&quot; {
  ami           = &quot;ami-12345678&quot;
  instance_type = &quot;t2.micro&quot;
}

# 2. 参数 (Argument)
name = &quot;value&quot;

# 3. 表达式 (Expression)
instance_count = 2 + 3
region         = var.aws_region

4.2 数据类型# 字符串 (String)
name = &quot;my-bucket&quot;

# 数字 (Number)
port = 8080

# 布尔值 (Bool)
enabled = true

# 列表 (List)
availability_zones = [&quot;us-west-2a&quot;, &quot;us-west-2b&quot;, &quot;us-west-2c&quot;]

# 映射 (Map)
tags = {
  Name        = &quot;MyServer&quot;
  Environment = &quot;Production&quot;
}

# 对象 (Object)
instance_config = {
  instance_type = &quot;t2.micro&quot;
  ami           = &quot;ami-12345678&quot;
  tags = {
    Name = &quot;WebServer&quot;
  }
}

4.3 引用和插值# 引用资源属性
resource &quot;aws_instance&quot; &quot;web&quot; {
  ami           = &quot;ami-12345678&quot;
  instance_type = &quot;t2.micro&quot;
}

resource &quot;aws_eip&quot; &quot;web_ip&quot; {
  instance = aws_instance.web.id  # 引用上面的实例 ID
}

# 引用变量
resource &quot;aws_s3_bucket&quot; &quot;data&quot; {
  bucket = var.bucket_name  # 引用变量
}

# 字符串插值
resource &quot;aws_s3_bucket&quot; &quot;logs&quot; {
  bucket = &quot;${var.project_name}-logs-${var.environment}&quot;
  # 结果可能是: &quot;myproject-logs-prod&quot;
}

# 引用数据源
data &quot;aws_ami&quot; &quot;ubuntu&quot; {
  most_recent = true
  owners      = [&quot;099720109477&quot;]
}

resource &quot;aws_instance&quot; &quot;web&quot; {
  ami = data.aws_ami.ubuntu.id  # 使用查询到的 AMI ID
}

4.4 函数Terraform 提供了丰富的内置函数：
# 字符串函数
upper(&quot;hello&quot;)          # &quot;HELLO&quot;
lower(&quot;HELLO&quot;)          # &quot;hello&quot;
join(&quot;-&quot;, [&quot;a&quot;, &quot;b&quot;])   # &quot;a-b&quot;
split(&quot;-&quot;, &quot;a-b-c&quot;)     # [&quot;a&quot;, &quot;b&quot;, &quot;c&quot;]

# 数值函数
max(1, 2, 3)            # 3
min(1, 2, 3)            # 1

# 集合函数
length([&quot;a&quot;, &quot;b&quot;, &quot;c&quot;]) # 3
concat([&quot;a&quot;], [&quot;b&quot;])    # [&quot;a&quot;, &quot;b&quot;]
contains([&quot;a&quot;, &quot;b&quot;], &quot;a&quot;) # true

# 日期函数
timestamp()             # &quot;2026-04-14T10:30:00Z&quot;

# 文件系统函数
file(&quot;config.txt&quot;)      # 读取文件内容

# 示例：在配置中使用函数
resource &quot;aws_s3_bucket&quot; &quot;logs&quot; {
  bucket = lower(&quot;${var.project_name}-LOGS&quot;)

  tags = merge(
    var.common_tags,
    {
      Name = &quot;Logs Bucket&quot;
    }
  )
}

4.5 条件表达式# 三元运算符
variable &quot;environment&quot; {
  default = &quot;dev&quot;
}

resource &quot;aws_instance&quot; &quot;web&quot; {
  instance_type = var.environment == &quot;prod&quot; ? &quot;t3.large&quot; : &quot;t3.micro&quot;
}

# 使用 count 实现条件创建
variable &quot;create_bucket&quot; {
  type    = bool
  default = true
}

resource &quot;aws_s3_bucket&quot; &quot;optional&quot; {
  count  = var.create_bucket ? 1 : 0  # 如果为 true 则创建，否则不创建
  bucket = &quot;my-optional-bucket&quot;
}

4.6 循环# for_each：遍历 map 或 set
variable &quot;users&quot; {
  default = {
    &quot;alice&quot; = &quot;admin&quot;
    &quot;bob&quot;   = &quot;user&quot;
    &quot;carol&quot; = &quot;user&quot;
  }
}

resource &quot;aws_iam_user&quot; &quot;users&quot; {
  for_each = var.users
  name     = each.key      # &quot;alice&quot;, &quot;bob&quot;, &quot;carol&quot;

  tags = {
    Role = each.value      # &quot;admin&quot;, &quot;user&quot;, &quot;user&quot;
  }
}

# count：创建多个相同资源
resource &quot;aws_instance&quot; &quot;web&quot; {
  count         = 3
  ami           = &quot;ami-12345678&quot;
  instance_type = &quot;t2.micro&quot;

  tags = {
    Name = &quot;web-${count.index}&quot;  # web-0, web-1, web-2
  }
}

# dynamic 块：动态生成嵌套块
variable &quot;ingress_rules&quot; {
  default = [
    { port = 80, protocol = &quot;tcp&quot; },
    { port = 443, protocol = &quot;tcp&quot; },
  ]
}

resource &quot;aws_security_group&quot; &quot;web&quot; {
  name = &quot;web-sg&quot;

  dynamic &quot;ingress&quot; {
    for_each = var.ingress_rules
    content {
      from_port   = ingress.value.port
      to_port     = ingress.value.port
      protocol    = ingress.value.protocol
      cidr_blocks = [&quot;0.0.0.0/0&quot;]
    }
  }
}


