九、实际应用示例9.1 完整的 AWS S3 + 复制示例这是一个简化的 Remote Backup 配置：
# versions.tf
terraform {
  required_version = &quot;&gt;= 1.5.0&quot;

  required_providers {
    aws = {
      source  = &quot;hashicorp/aws&quot;
      version = &quot;~&gt; 5.0&quot;
    }
  }

  backend &quot;s3&quot; {
    bucket         = &quot;my-terraform-state&quot;
    key            = &quot;remote-backup/terraform.tfstate&quot;
    region         = &quot;us-west-2&quot;
    encrypt        = true
    dynamodb_table = &quot;terraform-locks&quot;
  }
}

# providers.tf
provider &quot;aws&quot; {
  alias  = &quot;source&quot;
  region = &quot;us-west-2&quot;

  assume_role {
    role_arn = var.source_account_role
  }
}

provider &quot;aws&quot; {
  alias  = &quot;destination&quot;
  region = &quot;us-east-1&quot;

  assume_role {
    role_arn = var.destination_account_role
  }
}

# variables.tf
variable &quot;source_account_role&quot; {
  description = &quot;IAM role ARN for source account&quot;
  type        = string
}

variable &quot;destination_account_role&quot; {
  description = &quot;IAM role ARN for destination account&quot;
  type        = string
}

variable &quot;backup_prefix&quot; {
  description = &quot;Prefix for backup objects to replicate&quot;
  type        = string
  default     = &quot;databackup/&quot;
}

# main.tf
# 源备份桶
resource &quot;aws_s3_bucket&quot; &quot;source&quot; {
  provider = aws.source
  bucket   = &quot;source-backup-bucket&quot;

  tags = {
    Name      = &quot;Source Backup Bucket&quot;
    Purpose   = &quot;Remote Backup Source&quot;
    ManagedBy = &quot;Terraform&quot;
  }
}

# 启用源桶版本控制
resource &quot;aws_s3_bucket_versioning&quot; &quot;source&quot; {
  provider = aws.source
  bucket   = aws_s3_bucket.source.id

  versioning_configuration {
    status = &quot;Enabled&quot;
  }
}

# 目标备份桶
resource &quot;aws_s3_bucket&quot; &quot;destination&quot; {
  provider = aws.destination
  bucket   = &quot;destination-backup-bucket&quot;

  tags = {
    Name      = &quot;Destination Backup Bucket&quot;
    Purpose   = &quot;Remote Backup Destination&quot;
    ManagedBy = &quot;Terraform&quot;
  }
}

# 启用目标桶版本控制
resource &quot;aws_s3_bucket_versioning&quot; &quot;destination&quot; {
  provider = aws.destination
  bucket   = aws_s3_bucket.destination.id

  versioning_configuration {
    status = &quot;Enabled&quot;
  }
}

# IAM 角色用于复制
resource &quot;aws_iam_role&quot; &quot;replication&quot; {
  provider = aws.source
  name     = &quot;s3-replication-role&quot;

  assume_role_policy = jsonencode({
    Version = &quot;2012-10-17&quot;
    Statement = [
      {
        Action = &quot;sts:AssumeRole&quot;
        Effect = &quot;Allow&quot;
        Principal = {
          Service = &quot;s3.amazonaws.com&quot;
        }
      }
    ]
  })
}

# IAM 策略用于复制
resource &quot;aws_iam_policy&quot; &quot;replication&quot; {
  provider = aws.source
  name     = &quot;s3-replication-policy&quot;

  policy = jsonencode({
    Version = &quot;2012-10-17&quot;
    Statement = [
      {
        Action = [
          &quot;s3:GetReplicationConfiguration&quot;,
          &quot;s3:ListBucket&quot;
        ]
        Effect   = &quot;Allow&quot;
        Resource = aws_s3_bucket.source.arn
      },
      {
        Action = [
          &quot;s3:GetObjectVersionForReplication&quot;,
          &quot;s3:GetObjectVersionAcl&quot;,
          &quot;s3:GetObjectVersionTagging&quot;
        ]
        Effect = &quot;Allow&quot;
        Resource = &quot;${aws_s3_bucket.source.arn}/*&quot;
      },
      {
        Action = [
          &quot;s3:ReplicateObject&quot;,
          &quot;s3:ReplicateTags&quot;
        ]
        Effect = &quot;Allow&quot;
        Resource = &quot;${aws_s3_bucket.destination.arn}/*&quot;
      }
    ]
  })
}

# 附加策略到角色
resource &quot;aws_iam_role_policy_attachment&quot; &quot;replication&quot; {
  provider   = aws.source
  role       = aws_iam_role.replication.name
  policy_arn = aws_iam_policy.replication.arn
}

# 配置 S3 复制规则
resource &quot;aws_s3_bucket_replication_configuration&quot; &quot;replication&quot; {
  provider = aws.source

  bucket = aws_s3_bucket.source.id
  role   = aws_iam_role.replication.arn

  rule {
    id     = &quot;replicate-backups&quot;
    status = &quot;Enabled&quot;

    filter {
      prefix = var.backup_prefix
    }

    delete_marker_replication {
      status = &quot;Disabled&quot;
    }

    destination {
      bucket        = aws_s3_bucket.destination.arn
      storage_class = &quot;STANDARD&quot;

      metrics {
        status = &quot;Enabled&quot;
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.source,
    aws_s3_bucket_versioning.destination
  ]
}

# 目标桶策略（允许源账户复制）
resource &quot;aws_s3_bucket_policy&quot; &quot;destination&quot; {
  provider = aws.destination
  bucket   = aws_s3_bucket.destination.id

  policy = jsonencode({
    Version = &quot;2012-10-17&quot;
    Statement = [
      {
        Sid    = &quot;AllowReplicationFromSource&quot;
        Effect = &quot;Allow&quot;
        Principal = {
          AWS = aws_iam_role.replication.arn
        }
        Action = [
          &quot;s3:ReplicateObject&quot;,
          &quot;s3:ReplicateTags&quot;
        ]
        Resource = &quot;${aws_s3_bucket.destination.arn}/*&quot;
      }
    ]
  })
}

# outputs.tf
output &quot;source_bucket_id&quot; {
  description = &quot;Source bucket ID&quot;
  value       = aws_s3_bucket.source.id
}

output &quot;destination_bucket_id&quot; {
  description = &quot;Destination bucket ID&quot;
  value       = aws_s3_bucket.destination.id
}

output &quot;replication_role_arn&quot; {
  description = &quot;Replication IAM role ARN&quot;
  value       = aws_iam_role.replication.arn
}

